package zouitel.neighborhood.ai.embedding

/**
 * Ranks locally indexed notes by meaning, optionally blending existing FTS
 * relevance. This class has no database or Android dependencies and is safe to
 * execute on a background dispatcher.
 */
class SemanticSearchEngine(
    private val similarity: EmbeddingSimilarity = EmbeddingSimilarity(),
) {
    /**
     * @param query embedding generated by the same model as every candidate.
     * @param candidates candidates already restricted to the active user's
     * notes and to non-archived, non-deleted records by the caller.
     * @param limit maximum number of results.
     * @param minScore minimum final score in the inclusive range [0, 1].
     * @param semanticWeight contribution of semantic similarity. The lexical
     * contribution is the remaining weight.
     */
    fun search(
        query: EmbeddingVector,
        candidates: List<SemanticSearchCandidate>,
        limit: Int = 20,
        minScore: Double = 0.0,
        semanticWeight: Double = 0.8,
    ): List<SemanticSearchResult> {
        require(limit > 0) { "Result limit must be positive." }
        require(minScore.isFinite() && minScore in 0.0..1.0) {
            "Minimum score must be between 0 and 1."
        }
        require(semanticWeight.isFinite() && semanticWeight in 0.0..1.0) {
            "Semantic weight must be between 0 and 1."
        }
        if (candidates.isEmpty()) return emptyList()

        val maxLexicalScore = candidates.maxOf { it.lexicalScore }
        return candidates.map { candidate ->
            val cosine = similarity.cosine(query, candidate.embedding)
            // Cosine similarity is [-1, 1]; normalize it to [0, 1].
            val semantic = ((cosine + 1.0) / 2.0).coerceIn(0.0, 1.0)
            val lexical = if (maxLexicalScore > 0.0) {
                candidate.lexicalScore / maxLexicalScore
            } else {
                0.0
            }
            val score = semantic * semanticWeight +
                lexical * (1.0 - semanticWeight)
            SemanticSearchResult(
                noteId = candidate.noteId,
                score = score,
                semanticScore = semantic,
                lexicalScore = lexical,
            )
        }
            .asSequence()
            .filter { it.score >= minScore }
            .sortedWith(
                compareByDescending<SemanticSearchResult> { it.score }
                    .thenByDescending { it.semanticScore }
                    .thenBy { it.noteId }
            )
            .take(limit)
            .toList()
    }
}
